from pathlib import Path
import subprocess,os,signal
repo=Path('/Users/steventran/jobpipe');src=repo/'tools/ats_review_smoke.py';test=repo/'tests/test_ats_review_smoke.py'
base='591832cea7d132086751ab806d269f6e58f67bc0'
def git(*a):return subprocess.run(['git',*a],cwd=repo,check=True,capture_output=True,text=True).stdout
if git('rev-parse','HEAD').strip()!=base or git('rev-parse','origin/main').strip()!=base:raise SystemExit('AUTHORITY_CHANGED')
s=src.read_text();t=test.read_text()
if 'review_verified = all(' not in s or 'test_smoke_refuses_count_only_without_adapter_coverage' not in t:raise SystemExit('PREVIOUS_CHANGE_MISSING')
old='''"-q", "-v", "--tb=short", TEST,'''
new='''"-vv", "--tb=short", TEST,'''
if s.count(old)!=1:raise SystemExit('OUTPUT_FLAG_ANCHOR_CHANGED')
src.write_text(s.replace(old,new,1))
def run(args,seconds):
 p=subprocess.Popen(args,cwd=repo,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True)
 try:o,e=p.communicate(timeout=seconds)
 except subprocess.TimeoutExpired:
  os.killpg(p.pid,signal.SIGTERM)
  try:o,e=p.communicate(timeout=8)
  except subprocess.TimeoutExpired:os.killpg(p.pid,signal.SIGKILL);o,e=p.communicate()
  print('TIMEOUT',o[-1500:],flush=True);raise SystemExit(124)
 print('RESULT',p.returncode,o[-5200:],e[-700:],flush=True)
 return p.returncode,o
rc,_=run([str(repo/'.venv/bin/python'),'-m','pytest','-q','tests/test_ats_review_smoke.py'],80)
if rc:raise SystemExit('UNIT_FAILURE')
rc,out=run([str(repo/'.venv/bin/python'),str(src)],360)
if rc or 'ATS_FIXTURE_REVIEW_GATE=PASS' not in out:raise SystemExit('SMOKE_FAILURE')
subprocess.run(['git','add','--','tools/ats_review_smoke.py','tests/test_ats_review_smoke.py'],cwd=repo,check=True)
subprocess.run(['git','commit','-m','fix: report per-adapter ATS Review evidence from verbose pytest'],cwd=repo,check=True)
subprocess.run(['git','push','origin','main'],cwd=repo,check=True,timeout=90)
print('VERIFIED_PUSH',git('rev-parse','HEAD').strip(),flush=True)
